"""dat_id: UUIDv7 per RFC 9562, generated by the layer."""

import threading
import uuid
from collections.abc import Callable, Iterator

import pytest
from hypothesis import given
from hypothesis import strategies as st

from datorium.core.identity import IdGenerator, is_uuid7, new_id, timestamp_ms

MAX_MS = 2**48 - 1


def fixed_clock(values: list[int]) -> Callable[[], int]:
    it: Iterator[int] = iter(values)
    return lambda: next(it)


def zero_bits(n: int) -> int:
    return 0


def test_new_id_is_version_7_rfc_variant() -> None:
    value = new_id()
    assert isinstance(value, uuid.UUID)
    assert value.version == 7
    assert value.variant == uuid.RFC_4122
    assert is_uuid7(value)


def test_timestamp_is_the_unix_millisecond_of_generation() -> None:
    gen = IdGenerator(clock_ms=lambda: 1_760_000_000_123)
    assert timestamp_ms(gen()) == 1_760_000_000_123


@given(st.integers(min_value=0, max_value=MAX_MS))
def test_timestamp_round_trips(ms: int) -> None:
    gen = IdGenerator(clock_ms=lambda: ms)
    assert timestamp_ms(gen()) == ms


def test_ids_are_strictly_increasing_within_one_millisecond() -> None:
    gen = IdGenerator(clock_ms=lambda: 1_000)
    ids = [gen() for _ in range(5_000)]
    assert ids == sorted(ids)
    assert len(set(ids)) == len(ids)


def test_ids_stay_increasing_when_the_wall_clock_goes_back() -> None:
    gen = IdGenerator(clock_ms=fixed_clock([5_000, 4_000, 3_000]))
    a, b, c = gen(), gen(), gen()
    assert a < b < c
    assert timestamp_ms(c) == 5_000


def test_counter_overflow_moves_the_timestamp_forward() -> None:
    # A zero seed leaves 4096 counter values in one millisecond.
    gen = IdGenerator(clock_ms=lambda: 7_000, randbits=zero_bits)
    ids = [gen() for _ in range(4_097)]
    assert timestamp_ms(ids[4_095]) == 7_000
    assert timestamp_ms(ids[4_096]) == 7_001
    assert ids == sorted(ids)


def test_ids_are_increasing_and_unique_across_threads() -> None:
    gen = IdGenerator()
    per_thread: list[list[uuid.UUID]] = [[] for _ in range(8)]

    def work(out: list[uuid.UUID]) -> None:
        out.extend(gen() for _ in range(2_000))

    threads = [threading.Thread(target=work, args=(out,)) for out in per_thread]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    every = [i for out in per_thread for i in out]
    assert len(set(every)) == len(every)
    for out in per_thread:
        assert out == sorted(out)


@pytest.mark.parametrize("ms", [-1, MAX_MS + 1])
def test_clock_outside_48_bits_is_rejected(ms: int) -> None:
    gen = IdGenerator(clock_ms=lambda: ms)
    with pytest.raises(ValueError, match="48-bit"):
        gen()


@pytest.mark.parametrize(
    "value",
    [uuid.uuid4(), uuid.uuid1(), uuid.UUID(int=0), uuid.UUID(int=2**128 - 1)],
)
def test_other_uuids_are_not_uuid7(value: uuid.UUID) -> None:
    assert not is_uuid7(value)
    with pytest.raises(ValueError, match="UUIDv7"):
        timestamp_ms(value)


def test_known_vector_from_rfc_9562() -> None:
    # RFC 9562, Appendix A.6: 2022-02-22 19:22:22 UTC.
    value = uuid.UUID("017F22E2-79B0-7CC3-98C4-DC0C0C07398F")
    assert is_uuid7(value)
    assert timestamp_ms(value) == 0x017F22E279B0
